282	    public void saveOwner(Owner owner, boolean sharesHousehold) throws DataAccessException {
283	        boolean isCreate = owner.isNew();
284	        assertEmailDomainAllowed(owner);
285	        assertIdentityIsUnique(owner);
286	        if (owner.isNew()) {
287	            assertCityHasCapacity(owner);
288	            if (!sharesHousehold) {
289	                assertHouseholdIsUnique(owner);
290	            }
291	        }
292	        if (owner.getRegistrationDate() == null) {
293	            owner.setRegistrationDate(LocalDate.now());
294	        }
295	        assertRegistrationDateNotInFuture(owner);
296	        owner.setRegistrationDate(rollToBusinessDay(owner.getRegistrationDate()));
297	        if (owner.isNew()) {
298	            assertDailyRegistrationLimit(owner);
299	            owner.setBulkSignupWarning(computeBulkSignupWarning(owner));
300	        }
301	        if (owner.isNew() && owner.getCustomerCode() == null) {
302	            owner.setCustomerCode(generateCustomerCode(owner));
303	        }
304	        if (owner.isNew() && owner.getNamesakeCount() == null) {
305	            owner.setNamesakeCount(countNamesakes(owner));
306	        }
307	        if (owner.isNew()) {
308	            assignPossibleDuplicate(owner, sharesHousehold);
309	        }
310	        ownerRepository.save(owner);
311	        if (isCreate) {
312	            AUDIT.info("owner created id={} customerCode={} registrationDate={}",
313	                owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate());
314	        }
315	    }
316	
317	    /**
318	     * Count the existing owners that, at the moment this owner is created, share its first name
319	     * and last name (both compared case-insensitively). The owner being saved is excluded by id so
320	     * it never counts itself. This value is deterministic given the current data, so it is computed
321	     * once at creation time and stored.
322	     */
323	    private Integer countNamesakes(Owner owner) {
324	        String firstName = owner.getFirstName();
325	        String lastName = owner.getLastName();
326	        if (firstName == null || lastName == null) {
327	            return 0;
328	        }
329	        return (int) ownerRepository.findAll().stream()
330	            .filter(existing -> !Objects.equals(existing.getId(), owner.getId()))
331	            .filter(existing -> firstName.equalsIgnoreCase(existing.getFirstName())
332	                && lastName.equalsIgnoreCase(existing.getLastName()))
333	            .count();
334	    }
335	
336	    /**
337	     * Build an owner's {@code customerCode} formatted {@code '<REGION>-<HASH8>'}, where {@code REGION}
338	     * is the region code derived from the owner's postcode (or {@code 'UNKNOWN'} when no region can be
339	     * derived) and {@code HASH8} is the first eight upper-cased hex characters of SHA-256 over the
340	     * owner's normalized telephone concatenated with the last name (e.g. {@code 'NSW-1A2B3C4D'}). The
341	     * value is deterministic in those fields and carries no sequence number (see
342	     * {@link Owner#customerCode(String, String, String)}).
343	     */
344	    private String generateCustomerCode(Owner owner) {
345	        return Owner.customerCode(owner.getPostcode(), owner.getTelephone(), owner.getLastName());
346	    }
347	
348	    /**
349	     * Flag a newly created owner as a possible (soft) duplicate of an existing owner. A hard
350	     * duplicate (an owner reusing an existing normalized telephone) has already been rejected by
351	     * {@link #assertIdentityIsUnique(Owner)}, and an undeclared household duplicate by
352	     * {@link #assertHouseholdIsUnique(Owner)}, before this runs. This detects the weaker overlap: an
353	     * existing owner that shares this owner's household id (same last name and postcode, see
354	     * {@link Owner#householdId(String, String)}) but has a <em>different</em> normalized telephone.
355	     * When such an owner exists, {@code possibleDuplicate} is set {@code true} and
356	     * {@code possibleDuplicateOf} to the matching owner's id (the lowest id when several match);
357	     * otherwise {@code possibleDuplicate} is set {@code false} and {@code possibleDuplicateOf} left unset.
358	     *
359	     * <p>A declared household member ({@code sharesHousehold} set) is never a suspected duplicate: it
360	     * deliberately joins an existing household, so it is left unflagged.
361	     */
362	    private void assignPossibleDuplicate(Owner owner, boolean sharesHousehold) {
363	        if (sharesHousehold) {
364	            owner.setPossibleDuplicate(false);
365	            owner.setPossibleDuplicateOf(null);
366	            return;
367	        }
368	        String householdId = Owner.householdId(owner.getLastName(), owner.getPostcode());
369	        String normalizedTelephone = Owner.normalizeTelephone(owner.getTelephone());
370	        Integer match = null;
371	        if (householdId != null) {
372	            match = ownerRepository.findAll().stream()
373	                .filter(existing -> !Objects.equals(existing.getId(), owner.getId()))
374	                .filter(existing -> householdId.equals(
375	                    Owner.householdId(existing.getLastName(), existing.getPostcode())))
376	                .filter(existing -> !Objects.equals(normalizedTelephone,
377	                    Owner.normalizeTelephone(existing.getTelephone())))
378	                .map(Owner::getId)
379	                .filter(Objects::nonNull)
380	                .min(Integer::compareTo)
381	                .orElse(null);
382	        }
383	        owner.setPossibleDuplicate(match != null);
384	        owner.setPossibleDuplicateOf(match);
385	    }
386	
387	    /**
388	     * Enforce that the owner's email domain is not on the disposable-domain blocklist, throwing
389	     * {@link DisposableEmailDomainException} when it is. The blocklist check is the single source
390	     * of truth in {@link Owner#isDisposableEmailDomain(String)}; an owner with no email places no
391	     * constraint.
392	     */
393	    private void assertEmailDomainAllowed(Owner owner) {
394	        if (Owner.isDisposableEmailDomain(owner.getEmail())) {
395	            throw new DisposableEmailDomainException(owner.getEmail());
396	        }
397	    }
398	
399	    /**
400	     * Enforce that no <em>other</em> owner already shares this owner's derived identity, throwing
401	     * {@link DuplicateIdentityException} if one does. This single check consolidates the former
402	     * separate telephone, email and household duplicate checks into the one {@code identityKey}
403	     * (normalized telephone, normalized email (or empty) and household id, see
404	     * {@link Owner#identityKey(String, String, String, String)}).
405	     *
406	     * <p>Because the telephone is part of the key, two owners can only ever collide on the whole
407	     * key when their normalized telephones already match; the normalized telephone is therefore the
408	     * decisive component and is what this check compares. Consequently two members of the same
409	     * household with different telephones have different identity keys and are both allowed, while
410	     * an owner reusing an existing normalized telephone is rejected. The owner being saved is
411	     * excluded by id so updating an owner in place never conflicts with itself.
412	     */
413	    private void assertIdentityIsUnique(Owner owner) {
414	        String normalizedTelephone = Owner.normalizeTelephone(owner.getTelephone());
415	        if (normalizedTelephone == null) {
416	            return;
417	        }
418	        boolean duplicate = ownerRepository.findAll().stream()
419	            .filter(existing -> !Objects.equals(existing.getId(), owner.getId()))
420	            .map(existing -> Owner.normalizeTelephone(existing.getTelephone()))
421	            .anyMatch(normalizedTelephone::equals);
422	        if (duplicate) {
423	            throw new DuplicateIdentityException(Owner.identityKey(
424	                owner.getTelephone(), owner.getEmail(), owner.getLastName(), owner.getPostcode()));
425	        }
426	    }
427	
428	    /**
429	     * Enforce that no <em>other</em> owner already belongs to this owner's household, throwing
430	     * {@link DuplicateIdentityException} if one does. The household is keyed on {@code (lastName,
431	     * postcode)} (see {@link Owner#householdId(String, String)}), so owners sharing a last name and
